"""Generate full page contracts from the new-topic story ledger before building."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
story=json.loads((ROOT/'story-map.json').read_text())
clicks=[['Known P,C and radius','Mark the intended CCW quarter arc'],['Fixed axes and known P,C in the actual process scene','85-frame actual subtract-turn-add process; same arrow moves through all operations','Record the observed Q=P-C=(2,1)','Record the observed Qprime=(-1,2)','Record Pprime=C+Qprime=(1,3)'],['Known P,C','Translate both by -C once','Record Q=(2,1)'],['Q=(2,1)','Turn both legs and offset once','Record (-v,u)=(-1,2)'],["Known Qprime and C",'Translate the turned arrow by C once',"Record Pprime=(1,3)"],['General process with middle operation selected and the SAME Q in world context','29-frame focus: fade world context, build actual horizontal and vertical legs; hold exactly the next detail entry'],['Same selected rotation and exact focus endpoint','Turn the horizontal leg; mark theta and projections','Record signed projections from sine/cosine and length u'],['Retain H and unturned second leg; show known quarter-turn direction identity','Turn the second leg and join it to H, with local K leader','Record K using the known quarter turn','Add H+K; hold dominant general result'],['Exact preceding detail endpoint and the returned rule','29-frame return: carry this rotated arrow by C back into the originating process; keep its computed components','Add a to U','Add b to V'],['Change only theta to 30; retain returned rule','Substitute exact sin/cos','Demonstrate actual 30-degree rotation about C','Add C and hold exact answer'],['Full process and general rule with checks','Retain the requested numerical answer']]
contracts=[]
page_states=[s for s in story['states'] if s['id']!='focus-offset']
demo_ids={2:'process',3:'subtract',4:'quarter',5:'add',6:'focus',7:'horizontal',8:'vertical',9:'return',10:'thirty'}
for i,s in enumerate(page_states):
    contracts.append(dict(id=s['id'],slide=i+1,purpose=s['purpose'],narrativeRole=s['kind'],originatingScene=s['scene'],whyNow=s['why'],knownInput=s['requires'],newIncrement=clicks[i][1:] or clicks[i],dominantResult=s['produces'][-1:] or s['carries'][-1:] or s['activeObject'],conditions=['Cartesian coordinates; positive angle counterclockwise; equal axis scale','Example and general cases are explicitly identified'],clicks=[dict(stage=k,visible=v,hold='Retain necessary preceding work') for k,v in enumerate(clicks[i])],evidence=dict(source='Current prompt; source-ledger.md',demo=demo_ids.get(i+1),diagramPlacement=dict(x=70,y=300,w=1120,h=260) if 6<=i+1<=9 else None,numericalInvariants=['Distance to C preserved','Origin-based displacement matches subtraction','Two rotated legs add to the same endpoint']),continuation=page_states[i+1]['id'] if i<10 else 'Lesson complete',returnContract=dict(scene='general-process',retainedResult='rotation-rule',consumer='use-rule') if s.get('branch') else None,review=dict(teaching='pending visual pass',math='pending topic-check.py',nativePlayback='not-tested')))
(ROOT/'page-contract.json').write_text(json.dumps(dict(lesson=story['lesson'],mainRoute=['P','subtract C','rotate Q','add C','Pprime'],pages=contracts),indent=2),encoding='utf-8')
print('11 full page contracts generated before build.')
